570:export async function planPause(page: Page, planId: string, on: boolean): Promise<boolean> {
571:  const r = page.getByTestId(`plan-row-${planId}`);
572:  const done = async () => (await shown(r.getByTestId('plan-paused'))) === (on ? 'yes' : 'no');
574:  await r.getByTestId(on ? 'plan-pause' : 'plan-resume').click();
575:  return until(page, done, r.getByTestId('plan-error'), 'plan pause', already);
