    /**
     * Open each selected claim that can be opened, one at a time in list order (people in the order listed,
     * newest claim first within a person), so they are numbered in that order; each that cannot be opened, or is
     * not on the sheet, is refused and left as it is.
     */
    @PostMapping("/claims/bulk-open")
    public BulkOpenView bulkOpen(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody BulkOpen request) {
        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            // A viewer's bulk action, or one on an archived sheet, goes through with nothing done: every selected
            // claim is refused.
            return new BulkOpenView(0, (int) request.ids().stream().distinct().count(), List.of());
        }
        List<Long> ordered = claims.inListOrder(sheetId, request.ids());
        int refused = (int) request.ids().stream().distinct().count() - ordered.size();
        List<ClaimView> opened = new ArrayList<>();
        for (long id : ordered) {
            try {
                opened.add(ClaimView.of(claims.changeStatus(sheetId, user, id, ClaimStatus.OPEN)));
            } catch (ResponseStatusException refusal) {
                refused++;
            }
        }
        return new BulkOpenView(opened.size(), refused, opened);
    }

    /**
     * Settle every selected claim, one at a time in list order (people in the order listed, newest claim first
     * within a person), by exactly the rules of settling one claim; a claim a clerk's limit makes PENDING counts as
     * settled. All or nothing: when any selected claim cannot be settled, or is not on the sheet, none is settled,
     * every one is refused and nothing is written. Those settled are the sheet's next settle batch.
     */
    @PostMapping("/claims/bulk-settle")
    public BulkSettleView bulkSettle(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody BulkSettle request) {
        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            // A viewer's bulk action, or one on an archived sheet, goes through with nothing done: every selected
            // claim is refused.
            return new BulkSettleView(0, (int) request.ids().stream().distinct().count(), List.of(), null);
        }
        int selected = (int) request.ids().stream().distinct().count();
        List<Long> ordered = claims.inListOrder(sheetId, request.ids());
        List<Claim> settled = ordered.size() < selected ? null : claims.settleBatch(sheetId, user, ordered);
        if (settled == null) {
            // All or nothing: one selected claim that cannot be settled, or is not on the sheet, refuses them all.
            return new BulkSettleView(0, selected, List.of(), null);
        }
        List<ClaimView> batch = settled.stream().map(ClaimView::of).toList();
        return new BulkSettleView(batch.size(), 0, batch, batch.isEmpty() ? null : batch.get(0).batch());
    }

    /**
     * Move each selected claim to the person, one at a time in list order (people in the order listed, newest claim
     * first within a person), by exactly the rules of moving one claim. Each that cannot be moved, or is not on the
     * sheet, is refused and left as it is.
     */
    @PostMapping("/claims/bulk-reassign")
    public BulkReassignView bulkReassign(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody BulkReassign request) {
        int selected = (int) request.ids().stream().distinct().count();
        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            // A viewer's bulk action, or one on an archived sheet, goes through with nothing done: every selected
            // claim is refused.
            return new BulkReassignView(0, selected, List.of());
        }
        List<Long> ordered = claims.inListOrder(sheetId, request.ids());
        int refused = selected - ordered.size();
        List<ClaimView> moved = new ArrayList<>();
        for (long id : ordered) {
            try {
                moved.add(ClaimView.of(claims.reassign(sheetId, user, id, request.personId(), true)));
            } catch (ResponseStatusException refusal) {
                refused++;
            }
        }
        return new BulkReassignView(moved.size(), refused, moved);
    }
