        claim.setTerms(terms);
        boolean late = periods.existsBySheetIdAndSoftClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(
                sheetId, dueBy, dueBy);
        if (late) {
            claim.markLateEntry();
        }
        claim.setRef(reference);
        String tagged = tagsOf(tags);
        claim.setTags(tagged);
